  async function request(path,body) {const response=await fetch(endpoint(path),body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({version:state.version,...body})}:{});const data=await response.json();if(!response.ok)throw Object.assign(new Error(data.error||data.message||'请求失败，请重试'),{status:response.status});return data;}
