  function form(){const it=formDraft||(editing?active():null),project=getProject()||{};return `<form id="req-create" class="req-form"><h2>${editing?'迭代设置':'新建迭代'}</h2><p>给这次一起评审、开发和验收的改动起一个名字。</p><label>迭代名称<input name="name" maxlength="120" required value="${esc(it?.name||'')}" placeholder="例如：库存预警完善"></label><label>迭代场景<select name="scene">${Object.entries(scenes).map(([v,l])=>`<option value="${v}" ${it?.scene===v?'selected':''}>${l}</option>`).join('')}</select></label><label>本次范围<select name="scope">${Object.entries(scopes).map(([v,l])=>`<option value="${v}" ${it?.scope===v?'selected':''}>${l}</option>`).join('')}</select></label><fieldset class="req-pages" ${!it||it.scope!=='partial'?'hidden':''}><legend>关联页面（全部范围时自动包含所有页面）</legend>${(project.pages||[project.entry].filter(Boolean)).map(p=>`<label class="req-check"><input type="checkbox" name="pages" value="${esc(p)}" ${!it||it.pages?.includes(p)?'checked':''}>${esc(p)}</label>`).join('')}</fieldset><label>参考已完成的迭代<select name="baselineId"><option value="">无参考版本</option>${state.iterations.filter(i=>i.status==='done'&&i.id!==it?.id).map(i=>`<option value="${esc(i.id)}" ${it?.baselineId===i.id?'selected':''}>${esc(i.name)}</option>`).join('')}</select></label><label>补充说明<textarea name="note" rows="4" placeholder="特殊情况、已有功能、明确不做的部分……">${esc(it?.note||'')}</textarea></label><div class="req-actions"><button ${busy?'disabled':''} type="submit">${editing?'保存设置':'保存，稍后开始'}</button>${!editing?`<button type="submit" name="start" value="yes" class="req-primary" ${busy?'disabled':''}>开始迭代</button>`:''}${button('cancel-form','取消')}</div></form>`;}
