  async function deleteIteration(id){
    const iteration=state.iterations.find(i=>i.id===id);if(!iteration)return;
    const sheet=document.createElement('dialog');sheet.className='req-finish req-delete-confirm';
    sheet.setAttribute('aria-labelledby','req-delete-title');
    sheet.innerHTML=`<h2 id="req-delete-title">删除迭代「${esc(iteration.name)}」？</h2><p>将删除此迭代的需求文档、讨论、回答、资料及修改记录，删除后无法恢复。</p><p>关联的原型文件和其他迭代不会被删除。</p><div class="req-actions"><button type="button" data-cancel autofocus>取消</button><button type="button" class="req-danger" data-confirm>确认删除</button></div>`;
    document.body.append(sheet);sheet.showModal();
    const confirmed=await new Promise(resolve=>{
      const close=value=>{sheet.close();sheet.remove();resolve(value);};
      sheet.querySelector('[data-cancel]').onclick=()=>close(false);
      sheet.querySelector('[data-confirm]').onclick=()=>close(true);
      sheet.oncancel=event=>{event.preventDefault();close(false);};
    });
    if(!confirmed)return;
    if(id!==selected)await flush();
    const index=state.iterations.findIndex(i=>i.id===id),wasSelected=id===selected;
    await mutate('delete',{id,confirmed:true});
    try{const prefix=`${getProject()?.id}:${id}`;for(const storedKey of Object.keys(localStorage))if(storedKey===`requirements-composer:${prefix}`||storedKey.startsWith(`requirements-review:${prefix}:`)||storedKey.startsWith(`requirements-conflict:${prefix}:`))localStorage.removeItem(storedKey);}catch{}
    if(wasSelected){
      selected=(state.iterations[index]||state.iterations[index-1])?.id||'';
      dirty=false;docDraft='';editing=false;formMode=false;formDraft=null;quizMode='';quizId='';quizIndex=0;answerEditor=null;bodyRange=null;tab='document';
      composer='';try{composer=localStorage.getItem(key())||'';}catch{}
      render();
    }
    notice=`已删除迭代「${iteration.name}」。`;
  }
  async function finish(){if(hasDraft?.())throw new Error('原型有未保存修改，请先返回编辑器保存，再结束迭代。');await flush();const it=active(),pending=(it.suggestions||[]).filter(s=>!['accepted','applied'].includes(s.status));const sheet=document.createElement('dialog');sheet.className='req-finish';sheet.innerHTML=`<h2>结束本次迭代</h2><p>结束代表本轮需求工作结束，不代表开发或上线完成。</p><p>待确认问题：${it.questions?.length||0} 项 · 未完成同步：${pending.length} 项 · 待确认修改：${(it.documentReviews||[]).filter(r=>r.status==='pending').length} 项</p><ul>${(it.questions||[]).map(q=>'<li>'+esc(typeof q==='string'?q:q.text||q.question||q.title)+'</li>').join('')}${pending.map(s=>'<li>'+esc(s.title)+'</li>').join('')}</ul><label>结束说明（选填）<textarea rows="3"></textarea></label><div class="req-actions"><button data-confirm>保留上述事项并结束</button><button data-cancel>继续处理</button></div>`;document.body.append(sheet);sheet.showModal();await new Promise((resolve,reject)=>{sheet.querySelector('[data-cancel]').onclick=()=>{sheet.close();sheet.remove();resolve();};sheet.oncancel=()=>{sheet.remove();resolve();};sheet.querySelector('[data-confirm]').onclick=async()=>{sheet.querySelector('[data-confirm]').disabled=true;try{await mutate('finish',{note:sheet.querySelector('textarea').value});sheet.close();sheet.remove();resolve();}catch(e){sheet.remove();reject(e);}};});}
  dialog.addEventListener('input',e=>{if(e.target.matches('[data-conflict-explanation],[data-review-feedback]'))remember();if(e.target.closest('#req-answer-edit')&&answerEditor){if(e.target.name==='answer')answerEditor.text=e.target.value;if(e.target.name==='choice')answerEditor.choice=e.target.value===''?null:Number(e.target.value);}if(e.target.name==='question-count')questionCount=Number(e.target.value);if(e.target.name==='option-count')optionCount=Number(e.target.value);if(e.target.name==='question-answer'){const q=quizRound()?.questions[quizIndex];if(q){const draft=quizDrafts.get(q.id)||{choice:q.choice,text:q.textAnswer||''};quizDrafts.set(q.id,{...draft,text:e.target.value});}}if(e.target.name==='transcription-model')transcriptionModel=e.target.value;if(e.target.matches('[name="message"]'))remember();if(e.target.closest('.req-document-editor')){const editor=e.target.closest('.req-document-editor');docDraft=editor.matches('textarea')?editor.value:editableMarkdown(editor);dirty=true;const status=dialog.querySelector('[data-body-save-status]');if(status)status.textContent='有未保存修改';const b=dialog.querySelector('[data-action="save-doc"]');if(b){b.textContent='保存修改 *';b.disabled=false;}}});
  dialog.addEventListener('change',e=>{if(e.target.matches('[data-body-style]')){applyBodyFormat('formatBlock',e.target.value);return;}if(e.target.name==='scope'){dialog.querySelector('.req-pages').hidden=e.target.value!=='partial';}if(e.target.id==='req-upload'){const files=[...e.target.files];run(async()=>{await flush();for(const f of files)await addFile(f);});}});
  dialog.addEventListener('toggle',e=>{if(e.target.matches('.req-transcription-settings'))transcriptionSettingsOpen=e.target.open;},true);
  dialog.addEventListener('dragover',e=>{const zone=e.target.closest('.req-upload-zone');if(!zone||!e.dataTransfer?.types.includes('Files'))return;e.preventDefault();if(!busy&&active()?.status!=='done'){e.dataTransfer.dropEffect='copy';zone.classList.add('is-dragging');}else e.dataTransfer.dropEffect='none';});
  dialog.addEventListener('dragleave',e=>{const zone=e.target.closest('.req-upload-zone');if(zone&&!zone.contains(e.relatedTarget))zone.classList.remove('is-dragging');});
  dialog.addEventListener('drop',e=>{const zone=e.target.closest('.req-upload-zone');if(!zone)return;e.preventDefault();zone.classList.remove('is-dragging');if(busy||active()?.status==='done')return;const files=[...(e.dataTransfer?.files||[])];if(files.length)run(async()=>{await flush();for(const file of files)await addFile(file);});});
